package org.eclipse.rdf4j.rio.jsonld;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.ByteArrayInputStream;
import java.io.StringReader;
import java.nio.charset.StandardCharsets;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.Literal;
import org.eclipse.rdf4j.model.Model;
import org.eclipse.rdf4j.model.Statement;
import org.eclipse.rdf4j.model.impl.LinkedHashModel;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.model.vocabulary.XSD;
import org.eclipse.rdf4j.rio.helpers.StatementCollector;
import org.junit.jupiter.api.Test;

class JSONLDLargeLiteralTest {
	private static final int LARGE_LITERAL_LENGTH = 16_000_000;
	private static final String LARGE_LITERAL = "x".repeat(LARGE_LITERAL_LENGTH);
	private static final String JSON_LD = "{\"@id\":\"urn:large-jsonld:subject\","
			+ "\"urn:large-jsonld:predicate\":{\"@value\":\"" + LARGE_LITERAL + "\"}}";

	private static final IRI EXPECTED_SUBJECT = SimpleValueFactory.getInstance()
			.createIRI("urn:large-jsonld:subject");
	private static final IRI EXPECTED_PREDICATE = SimpleValueFactory.getInstance()
			.createIRI("urn:large-jsonld:predicate");

	@Test
	void preservesLargeLiteralFromReader() throws Exception {
		Model statements = parse(new StringReader(JSON_LD));

		assertSingleExpectedStatement(statements);
	}

	@Test
	void preservesLargeLiteralFromInputStream() throws Exception {
		byte[] jsonLdBytes = JSON_LD.getBytes(StandardCharsets.UTF_8);
		Model statements = parse(new ByteArrayInputStream(jsonLdBytes));

		assertSingleExpectedStatement(statements);
	}

	private static Model parse(StringReader reader) throws Exception {
		JSONLDParser parser = new JSONLDParser();
		Model statements = new LinkedHashModel();
		parser.setRDFHandler(new StatementCollector(statements));
		parser.parse(reader, "");
		return statements;
	}

	private static Model parse(ByteArrayInputStream inputStream) throws Exception {
		JSONLDParser parser = new JSONLDParser();
		Model statements = new LinkedHashModel();
		parser.setRDFHandler(new StatementCollector(statements));
		parser.parse(inputStream, "");
		return statements;
	}

	private static void assertSingleExpectedStatement(Model statements) {
		assertEquals(1, statements.size(), "A single JSON-LD property should produce one statement");
		Statement statement = statements.iterator().next();
		assertEquals(EXPECTED_SUBJECT, statement.getSubject());
		assertEquals(EXPECTED_PREDICATE, statement.getPredicate());
		assertTrue(statement.getObject() instanceof Literal, "The JSON-LD value should be a literal");

		Literal literal = (Literal) statement.getObject();
		assertTrue(LARGE_LITERAL.equals(literal.getLabel()), "The parser should preserve the complete literal value");
		assertEquals(XSD.STRING, literal.getDatatype());
		assertTrue(literal.getLanguage().isEmpty(), "The literal should not have a language tag");
		assertNull(statement.getContext(), "The JSON-LD statement should not have a context");
	}
}
